// encodeObjHeader encodes a pack object header for the given type and size.
func encodeObjHeader(typ byte, size uint64) []byte {
	first := (typ&7)<<4 | byte(size&0x0f)
	size >>= 4
	var out []byte
	for size > 0 {
		out = append(out, first|0x80)
		first = byte(size & 0x7f)
		size >>= 7
	}
	out = append(out, first)
	return out
}

